window.STORY_CHAPTERS["c78ad6f72b2f27f89"]={"id":"c78ad6f72b2f27f89","lines":[{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_1#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_1","speaker":{"ja":"アスナ"},"text":{"cn":"欸，你要不要也去找人组队啊？找不到人的话……我是可以帮你啦。","en":"Say, why don't you join a party? If you can't find anyone else... I wouldn't mind helping out.","ja":"ねえ、君も誰かとパーティ組んだら?誰もいないなら……わたしが手伝ってもいいけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_2#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就算遇上烦心事，只要下厨我就能把那些事抛在脑后，而且煮完还能享受美味佳肴呢。","en":"Cooking always makes me forget my troubles. And the tasty meal at the end is a nice bonus.","ja":"イヤなことがあっても、料理をするとなんだか忘れられるんだ終わればおいしいご飯も食べられるし"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_3#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我一直以来都把攻略游戏摆在第一顺位，但最近已经不是如此了。我会变成这样，也都是因为你……","en":"I used to prioritize raids above all else, but that's changed recently. Maybe you played a hand in that...","ja":"ずっと、攻略が最優先だって思って来たけど、最近は変わってきたのこうなったのも、君の……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_4#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你那身黑漆漆的装扮，不能稍微改改吗？至少上街的时候换一套衣服……","en":"Would you mind changing up that all-black look of yours? At least when we're in town...","ja":"君の、その黒ずくめの格好何とかならないの?せめて街にいるときくらい……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_5#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"欸，我今天带了便当过来。你不介意的话，要不要找个地方一起享用呢？","en":"Smile! I brought us lunch today. Want to go on a picnic with me?","ja":"ね、今日はお弁当を持ってきたのよかったら、これを持ってどこかに行かない?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_6#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你是很厉害没错，但还是有些地方叫人放不下心。所以，我没办法扔下你不管。","en":"You're really strong, but you can be a loose cannon sometimes. You'd be hopeless without me.","ja":"君ってすごく強いけど少し危なっかしいところがあるのよだから、放っておけないの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_7#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"都置身在死亡游戏里了，人与人之间却还是纷争不断呢。大家怎么不好好相处呢？","en":"It's sad enough that we're in this death game—why must we kill each other, too? We should all be friends.","ja":"こんなデスゲームの中なのに人同士の争いはなくならないねもっと仲良くすればいいのになあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_8#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然你摆出一副孤傲的样子，但朋友其实也满多的嘛，像是戴头巾的人，还有情报商人等等。","en":"You may act like a loner, but between that bandana guy and the informant, you actually do have a few friends.","ja":"孤高ぶってるけど、バンダナの人とか情報屋さんとか……仲良しも結構いるんだよね、君"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_2nd_anniv_9#originalText","id":"talk.vc.home_wait_asuna_sao_2nd_anniv_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"欸，你怎么了？啊，我知道了，你又困了对吧？真是的，你昨天熬夜了吧？","en":"Is something wrong? Oh, I know. You're still sleepy. Jeez, serves you right for staying up so late.","ja":"ねえ、どうしたの?あ、わかった。また眠いのねまったく、昨日夜更かししたんでしょ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_2nd_anniv_1#originalText","id":"talk.vc.home_touch_asuna_sao_2nd_anniv_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"喂！顾虑一下时间跟场合啊！真是的，有人在看啦……","en":"Stop that! This is neither the time nor the place! Goodness. People are watching...","ja":"ちょっと!時と場所を考えなさいよね!まったく、人が見てるじゃない……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_2nd_anniv_2#originalText","id":"talk.vc.home_touch_asuna_sao_2nd_anniv_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我有时也会觉得头发在战斗时很碍事，不过，我想维持这个发型。这个我刚开始玩游戏时的发型。","en":"Sometimes my hair does get in the way. But I want to keep it like this... how it was when I started the game.","ja":"髪が戦いの邪魔になるときもあるわでも、この髪型でいたいのゲームを始めたときの、この髪型で"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_2nd_anniv_3#originalText","id":"talk.vc.home_touch_asuna_sao_2nd_anniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……欸，你以为这样随意乱摸女孩子的脸，是可以被容许的行为吗？","en":"Um...friendly advice, don't touch a girl's face like that unless you want to get on her bad side.","ja":"……あのね、女の子の顔にそんな気軽にタッチして許されると思ってるの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_2nd_anniv_4#originalText","id":"talk.vc.home_touch_asuna_sao_2nd_anniv_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你再继续摸我的话，会触犯伦理规范喔！","en":"If you keep your hand there one second longer, the moral code will activate!","ja":"それ以上触ったら倫理コードが発動するからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_2nd_anniv_5#originalText","id":"talk.vc.home_touch_asuna_sao_2nd_anniv_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……既然你说这是「不小心」，那可以请你解释一下，为什么你两只手都在摸这里吗？","en":"You insist it's an \"accident,\" but would you mind explaining exactly how both your hands got there?","ja":"……これがもし「うっかり」だって言うなら、両手ともここを触ってる理由を説明してもらえるかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_2nd_anniv_6#originalText","id":"talk.vc.home_touch_asuna_sao_2nd_anniv_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我也是用比较轻的装备。毕竟挥舞细剑时，敏捷度至关重要嘛。","en":"I also like to dress light. And I use a rapier because I value swiftness over all else.","ja":"わたしも、装備は軽目なのレイピアを使うには、やっぱり素早さが重要だし"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_2nd_anniv_7#originalText","id":"talk.vc.home_touch_asuna_sao_2nd_anniv_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要、要是被情报商人之类的人瞧见我们这个样子，你打算怎么办！？","en":"H-Hey, what if the informant sees us like this?!","ja":"こ、こんなところ情報屋さんにでも見つかったらどうするつもりなの!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_2nd_anniv_8#originalText","id":"talk.vc.home_touch_asuna_sao_2nd_anniv_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就叫你看一下时间跟地点了！……如果是在气氛好一点的地方，我当然也……没、没事啦！","en":"Again, this is neither the time nor the place! I mean, if we at least had... N-Never mind!","ja":"だから時と場所を考えなさいってば!……わたしだって、雰囲気のあるところでなら……な、なんでもない!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_1#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你竟然这么早起，真让人惊讶。今天是不是会下雪啊？","en":"I'm surprised to see you up so early. Is it gonna snow today or something?","ja":"君がこんなに朝早く起きてるなんて、びっくりだわ今日は雪が降るのかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_2#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"好了，快去刷牙洗脸吧。乖乖照我的话做，我就破例做早餐给你吃喔。","en":"Come on, at least go wash your face. Then I'll cook a special breakfast just for you.","ja":"ほら、顔でも洗ってきなさいそうしたら、特別に朝ご飯を作ってあげるから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_3#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你该不会现在才要睡吧？真是的，这样身体会吃不消的喔！","en":"Wait, I hope you're not just going to bed now? Goodness... Don't cry to me when you get sick.","ja":"もしかして、これから寝るんじゃないでしょうね。まったくそれじゃ体壊しちゃうわよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_4#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"早啊，你起得真晚！真是的，亏你能睡到这时候。","en":"Good afternoon, sleepy-head! You know, I'm almost impressed by how late you can sleep in.","ja":"おそようさま!まったく、こんな時間までよく寝ていられるわね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_5#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"攻略也告一段落了，今天似乎能难得放松一下呢。","en":"With the raid out of the way, looks like I finally get an afternoon off.","ja":"攻略も一段落して、今日は久しぶりにのんびりできそうね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_6#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天天气这么好，却要开公会的联系会议，要开也该选在户外啊。","en":"I hate that I have a guild meeting today when the weather's so nice. We should at least have it outside.","ja":"今日はこんなにいい天気なのにギルドの連絡会があるのどうせなら、外でやればいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_7#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我晚上都尽量不出门。因、因为……说不定……会有鬼啊。","en":"I try not to go out at night. I m-mean...there might be... ghosts and stuff.","ja":"夜は、なるべく出かけないようにしてるの。だ、だって……お化けが出る……かもしれないし"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_8#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"看到热闹的店家，我就觉得很放心。因为这代表那里的人都过得不错。","en":"I always feel a sense of calm when I see a bustling shop. It means everyone in there is happy.","ja":"賑わってるお店を見るとなんだかホッとするのそこのみんなが元気って事だから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_9#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呼啊……想睡觉了。我先去休息了喔，晚安。","en":"Yawwwn... Oh, my. I'm sleepy. I guess I'll turn in early, then. Goodnight.","ja":"ふわあ……眠くなって来ちゃったわたしは先に休むわねおやすみなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_10#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"半夜自己醒来时，总会觉得有点寂寞呢。你是不是也有这种感受？","en":"I always feel so lonely, waking up alone in the middle of the night. Wait...do you feel lonely, too?","ja":"夜中にひとりで目を覚ましちゃうとなんだか寂しいよねもしかして、君も同じ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_11#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"都是因为陪你一起睡午觉，害我在奇怪的时间醒来了。你可要负起责任，陪我到天亮喔！","en":"Looks like that nap I took with you made me wake up too early. You'd better keep me entertained!","ja":"君に付き合ってお昼寝したから変な時間に目が覚めちゃった責任取って、朝まで付き合ってね!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_2nd_anniv_12#originalText","id":"talk.vc.home_time_asuna_sao_2nd_anniv_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"大半夜的还要出门？真拿你没办法，我也陪你一起去吧。","en":"You're going out? This late at night? Oh, fine...I'll keep you company.","ja":"こんな夜中にお出かけ?もう、仕方ないなあわたしも一緒に行ってあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_2nd_anniv_1#originalText","id":"talk.vc.home_day_asuna_sao_2nd_anniv_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"每到星期一，我都会提醒自己要抬头挺胸、提起精神，好让自己不管何时回到现实都能适应。","en":"I try to be extra-sharp on Mondays... so I'll be prepared for the real world if we ever make it back.","ja":"月曜日は、意識して背筋を伸ばすようにしてるのいつ現実に戻ってもいいように"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_2nd_anniv_2#originalText","id":"talk.vc.home_day_asuna_sao_2nd_anniv_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"公会会议、物资补给，还要准备攻略会议跟联系……完全没有在玩游戏的感觉啊。","en":"Between guild meetings, stocking supplies, and prepping for raids... this doesn't feel at all like a game.","ja":"ギルドの会議に物資の補給攻略会議の準備と連絡……全然ゲームって気がしないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_2nd_anniv_3#originalText","id":"talk.vc.home_day_asuna_sao_2nd_anniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天我要配合日历上的红字，放自己一天假。我要大玩特玩啰～！","en":"I've synced up my schedule so we can take the day off together. Let's totally spread our wings!","ja":"カレンダーに合わせて、今日はわたしも一日お休み思いっきり羽根を伸ばすぞー!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_2nd_anniv_4#originalText","id":"talk.vc.home_day_asuna_sao_2nd_anniv_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就算是在游戏的世界，星期日深夜还是会让人觉得依依不舍。这是否也代表自己过得很愉快呢？","en":"Sunday evenings always come too fast—even in-game. I guess that means we had a great time.","ja":"ゲームの中でも、日曜の深夜ってなんだか名残惜しくなっちゃうそれだけ楽しかったってことかな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_1#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"新年快乐。在游戏里过年其实也挺不错呢。","en":"Happy New Year. I suppose spending New Year's in a game isn't all bad.","ja":"あけましておめでとうゲームの中でお正月って言うのも案外悪くないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_2#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"节分的豆子，需要使用《投掷》技能来丢吗？这样的话，代表还需要先具备《体术》……？","en":"I wonder if Setsubun beans require the \"Throw\" skill? If so, I guess I'll need Martial Arts as a prerequisite?","ja":"節分の豆は、《投擲》スキルで投げるのかしら。だとしたら前提として《体術》が必要……?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_3#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不用露出那种眼神，我有准备你的分啦。来，巧克力，姑且是我自己做的。","en":"Stop staring. I can take a hint. Here. Happy Valentine's Day. And yes, they are homemade.","ja":"そんな目で見なくてもちゃんと用意してあるわよはい、チョコレート。一応手作りよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_4#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我做了雏米果，没想到大家都还挺喜欢的。原来男生也会吃雏米果啊。","en":"I made some Hinamatsuri crackers, and everyone actually loved them. Even the boys!","ja":"雛あられを作ったら、案外みんなに喜んでもらえたの男の子も食べるのね、雛あられ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_5#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"咦？要送我？……谢谢你，我好高兴。真没想到……能收到你送的礼物。","en":"Is that...for me? Oh, thank you! That's so sweet. Wow...a gift from you.","ja":"え、わたしに?……ありがとう、すごくうれしいだって……君からもらえるなんて"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_6#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"怎么可以说谎呢？为了不让你变成骗子，我今天一整天会看好你的。","en":"Don't you dare lie today. I'm going to stay with you all day to make sure you're honest!","ja":"駄目よ、嘘なんてあなたが嘘をつかないように今日は一日ついていきますからね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_7#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我以前连假都在念书，像这样拿来玩游戏，反而让我感到很不可思议。","en":"I'd always spent my vacations studying, so playing a game like this feels rather surreal.","ja":"連休って、ずっと勉強ばっかりしてたから、なんだかこうしてゲームをしてるのが不思議な感じ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_8#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就算是在虚拟空间，还是感受得到湿气带来的不适呢……啊，好想快点洗澡啊！","en":"Never thought I'd feel so sticky from rainy season in a virtual world... Oh, I wish I could take a shower!","ja":"仮想空間でも、湿気の不快さは感じるのね……ああ、もう早くお風呂に入りたい!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_9#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"七夕这个节日真是不可思议呢。为什么织女和牛郎的故事，会跟许愿扯上关系啊？","en":"Tanabata sure is strange, isn't it? What does a celestial love story have to do with granting wishes?","ja":"七夕って不思議な行事よね織姫と彦星の物語に、どうして願い事がリンクしたのかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_10#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"没想到这个世界也有祭典的摊贩……呵呵，看了不禁就开心起来了呢。","en":"Haha, can you believe it? Festival stalls in this world! They do make me smile, though.","ja":"この世界にも、お祭りの屋台が出てるなんて……ふふ、見るとやっぱり楽しい気分になってくるわね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_11#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我记得每到暑假最后一天，我都是和朋友一起赶作业。不用怀疑，我当然是负责指导的人。","en":"I think I always spent the last day of summer break in study camp with friends. I was the teacher, of course.","ja":"夏休み最終日は、いつも友達と一緒に宿題してたっけもちろん、わたしは教える側よ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_12#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"听说在不同国家，看到的月亮纹路也不一样……不知道《SAO》的月亮上住着什么？","en":"I heard Moon lore is different all over the world...but I wonder if there's life on the Moon in SAO lore?","ja":"月の模様は国によって違うって言うけど……《SAO》の月には何が住んでいるのかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_13#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_13","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这种变装的衣服，平常明明穿不到……但我还是不小心买下去了。……不行，下次再穿给你看。","en":"I usually don't get VR costumes... but I bought one. Oh, nooo, not yet. I'll show it to you later.","ja":"仮想用の衣服なんて、普段使わないのに……思わず買っちゃった……だーめ、見せるのはまた今度ね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_14#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"初始之日虽然让人难以忘怀，但感觉自己又多活了一年……不禁有点欣慰。","en":"I'll never forget that first day. But I survived a year! That makes me feel a sense of pride...and joy.","ja":"始まりの日は忘れないけどまた一年生き延びたっていう実感というか……うれしさはあるかも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_2nd_anniv_15#originalText","id":"talk.vc.home_event_asuna_sao_2nd_anniv_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"难得的圣诞节，我们也来享受过节的气氛吧。有什么关系，就今天而已嘛。","en":"Since it's Christmas, we might as well make the most of it and live a little!","ja":"せっかくのクリスマスだしわたしたちも一緒に楽しもうかいいじゃない、今日くらいは"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_sao_2nd_anniv_1#originalText","id":"talk.vc.home_season_asuna_sao_2nd_anniv_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要是这个世界也有地方能赏花就好了呢。这样的话，我就会准备便当了。","en":"I wish this world had cherry groves. Then we could have a spring picnic under the cherry blossoms.","ja":"この世界にも、お花見ができる場所があるといいのにねそうしたら、お弁当作るのに"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_sao_2nd_anniv_2#originalText","id":"talk.vc.home_season_asuna_sao_2nd_anniv_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"比起潮湿的天气，还是万里无云的大热天要好得多呢。","en":"If it's going to be so humid, I'd almost rather the weather just be super hot and sunny.","ja":"ジメジメしてるくらいならカラッと晴れて暑い方がいいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_sao_2nd_anniv_3#originalText","id":"talk.vc.home_season_asuna_sao_2nd_anniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然在现实世界里，能感受到秋意的日子越来越短了，但《SAO》似乎没有这种情况呢。","en":"In the real world, it's feeling less and less like autumn, but that doesn't seem to be the case in SAO.","ja":"現実世界だと秋を感じる日ってどんどん短くなってるけど《SAO》ではそんなことないみたいね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_sao_2nd_anniv_4#originalText","id":"talk.vc.home_season_asuna_sao_2nd_anniv_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天下雪了呢。这种天气真不想出门啊，我们今天就都待在家里吧？","en":"I always feel like staying in on snowy days like this. Would you like to just do that?","ja":"今日は雪が降ってるのねこんな日は外に出たくないなあ一日、お家にいることにしようか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_2nd_anniv_2#originalText","id":"talk.vc.home_bd_asuna_sao_2nd_anniv_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"咦？原来你知道我什么时候过生日啊……嗯，我很开心，谢谢你！","en":"What? How did you know...? Well, thank you. That's so sweet of you!","ja":"えっ、わたしの誕生日知ってたんだ……うん、うれしいよ。ありがとう!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_2nd_anniv_3#originalText","id":"talk.vc.home_bd_asuna_sao_2nd_anniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是桐人的生日，我跟情报商人买了礼物要送他，不晓得他会不会喜欢。","en":"It's Kirito's birthday. I know— the informant told me so. I hope he likes my present.","ja":"今日はキリトくんの誕生日ちゃんと情報屋さんから仕入れたのプレゼント、喜んでもらえるかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_2nd_anniv_5#originalText","id":"talk.vc.home_bd_asuna_sao_2nd_anniv_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是爱丽丝的生日呢。我负责准备料理，派对的筹备就交给你了。","en":"Yay, it's Alice's birthday. I'll do the cooking, so you set up for the party, okay?","ja":"今日はアリスの誕生日ね料理はわたしが作るから君はパーティーの準備をお願い"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_2nd_anniv_7#originalText","id":"talk.vc.home_bd_asuna_sao_2nd_anniv_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是你妹妹的生日对吧？嗯，我们一起庆祝吧，我想你妹妹一定也会很高兴的。","en":"Oh, it's your little sister's birthday! Yeah, I'll help you throw a party. I'm sure she'll love that.","ja":"今日はリーファちゃんの誕生日なのよね。うん、一緒に祝いましょうきっとリーファちゃんも喜ぶと思うわ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_2nd_anniv_8#originalText","id":"talk.vc.home_bd_asuna_sao_2nd_anniv_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天小诗诗的生日喔。如果收到我们一起挑的礼物，她一定会很高兴的。","en":"Hey, it's Shino-non's birthday. I think she'd like it best if we picked her present together.","ja":"シノのんの誕生日よプレゼント、ふたりで選んだらきっと喜んでもらえると思うの"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_2nd_anniv_9#originalText","id":"talk.vc.home_bd_asuna_sao_2nd_anniv_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是有纪的生日，其实她指名要跟你对战……她想要认真地打一回。","en":"Today's Yuuki's birthday and I actually had a favor to ask... She says she wants a proper fight.","ja":"今日はユウキの誕生日なの実は、君にリクエストがあって……本気で戦いたいんだって"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_2nd_anniv_14#originalText","id":"talk.vc.home_bd_asuna_sao_2nd_anniv_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"莉兹过生日，我打算送她店里用得上的道具。她应该最喜欢实用的礼物吧。","en":"I was thinking of getting Liz some blacksmith tools for her birthday. I figured she'd like that the most.","ja":"リズの誕生日には、お店で使える道具を送ろうと思うのそれが一番喜んでもらえるかなって"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_2nd_anniv_15#originalText","id":"talk.vc.home_bd_asuna_sao_2nd_anniv_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是西莉卡的生日吧？我想为毕娜挑个宠物饰品，送给她当礼物。","en":"It's Silica's birthday today, isn't it? I'm thinking of getting her something cute for Pina to wear.","ja":"シリカちゃん、今日がお誕生日よねピナに似合う、ペット用のアクセサリーを贈ろうと思うんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_sao_2nd_anniv_1#originalText","id":"talk.vc.home_etc_asuna_sao_2nd_anniv_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"前阵子刚出的任务，你已经通过了？呵呵，真是卖力呢。","en":"Wow, you already cleared the quest? Haha, you sure are eager.","ja":"この前のクエストもうクリアしたの?ふふ、張り切ってるのね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_sao_2nd_anniv_2#originalText","id":"talk.vc.home_etc_asuna_sao_2nd_anniv_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你不是有收到礼物的通知吗？要不要打开看看？里面说不定有很棒的东西喔。","en":"A gift arrived for you. Come on, open it! It might be something great.","ja":"ギフトの通知が来てるでしょほら、開けてみたら?ステキな物が入ってるかも"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_sao_2nd_anniv_3#originalText","id":"talk.vc.home_etc_asuna_sao_2nd_anniv_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"已经做好下次攻略的准备了吗？是的话，我们就赶紧出发吧！","en":"Are you ready for the next raid? If you are, let's head right out!","ja":"次の攻略の準備はできた?準備ができてるならさっそく出発しましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_1#originalText","id":"talk.vc.home_wait_asuna_alo_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"沉睡骑士真的很出色。大家都很温柔，我待在这里也觉得很安心。","en":"Those Sleeping Knights are truly great. They're nice and so easygoing!","ja":"スリーピングナイツってとっても素敵ね。みんな優しくてすごく居心地がいいの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_2#originalText","id":"talk.vc.home_wait_asuna_alo_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"一开始我也吓了一跳。没想到，《绝剑》竟然是女生。","en":"I was surprised at first. I would have never had thought that the Absolute Sword was a woman!","ja":"最初はビックリしたわよまさか、《絶剣》が女の子だなんて思わなかったもの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_1#originalText","id":"talk.vc.home_touch_asuna_alo_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"被你这样对待，我完全不觉得讨厌。……我也可以碰你吗？","en":"It doesn't bother me when you do it... Could I also touch it?","ja":"あなたにそうされるのは全然イヤじゃないな……わたしも、触っていい?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_4#originalText","id":"talk.vc.home_touch_asuna_alo_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"怎么了？我知道了，你想撒娇吧？好吧，过来我这里。","en":"What happened? I got it, you want to cuddle, don't you? It's ok, come on over!","ja":"どうしたの?わかった、甘えたいんでしょ?いいわよ、こっちにきて"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_5#originalText","id":"talk.vc.home_touch_asuna_alo_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"像这样，感受到你的体温，我就会安心下来。","en":"For some reason... When I feel your warmth like this, all my worries go away.","ja":"こうやって、あなたのぬくもりが感じられると、なんだか安心するの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_1#originalText","id":"talk.vc.home_time_asuna_alo_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"早安，今天我们要一整天都在一起喔！","en":"Morning! Looks like we'll be together all day today!","ja":"おはよう今日は、一日中ずっと一緒にいようね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_4#originalText","id":"talk.vc.home_time_asuna_alo_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天的天气很好，我们今天就不要去狩猎，悠闲地过一天好吗？","en":"Since the weather is so nice, how about we skip on hunting and just relax today?","ja":"今日は暖かくて気持ちがいいから狩りに行かずにのんびり過ごすことにしない?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_7#originalText","id":"talk.vc.home_time_asuna_alo_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我在那边发现了很有趣的食谱，我会试试看在这边重现出来的。","en":"I found a very interesting recipe over there, so I'll try to reproduce it here.","ja":"向こうで面白いレシピを見つけたから、こっちで再現してみるわね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_10#originalText","id":"talk.vc.home_time_asuna_alo_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"很困，可是我不想睡。因为我想跟你渡过更多更多的时间。","en":"I'm tired but don't want to sleep just yet. Because I want to spend a little more time with you. ","ja":"眠いけど、寝たくないあなたと一緒の時間をもっともっと過ごしたいから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_alo_1#originalText","id":"talk.vc.home_day_asuna_alo_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"星期一的早上总是很困，但是我觉得只要星期一努力过的话，整个星期就不会有问题了！","en":"Monday mornings are a real slog, but if you do your best on Monday, then the rest of the week should be a breeze!","ja":"月曜の朝って眠いけど月曜が頑張れればその一週間はずっと大丈夫って感じ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_alo_2#originalText","id":"talk.vc.home_day_asuna_alo_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"如果我的成绩退步就没办法再来ALO了……所以要努力读书才行。","en":"If my grades fall behind I won't be able to log onto ALO... I have to try hard for my studies too!","ja":"成績を落とすとALOに来られなくなっちゃうから……勉強も頑張らないと"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_alo_3#originalText","id":"talk.vc.home_day_asuna_alo_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天一整天都可以在一起呢！好了，做什么好呢？","en":"Looks like we'll be together all day today! What do you want to do?","ja":"今日はずっと一緒にいられるね!さあ、何をしてすごしましょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_alo_4#originalText","id":"talk.vc.home_day_asuna_alo_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"愉快的假期结束了呢。现在已经开始期待下一个假期了。","en":"There goes another fun vacation. And now the long wait for the next.","ja":"楽しい休みが終わっちゃったね今から、次のお休みが待ち遠しいな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_alo_1#originalText","id":"talk.vc.home_season_asuna_alo_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"只要积雪溶化，春天就要来了。我们一起去哪里玩吧。","en":"When the snow melts, that means spring has finally arrived. Shall we go somewhere for the occasion?","ja":"雪が溶ければ、いよいよ春の到来ね一緒にどこへ行きましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_alo_2#originalText","id":"talk.vc.home_season_asuna_alo_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我们一起去海边吧？去一个没什么人安静的沙滩聊天。","en":"Should we go to the beach? There's not that many people around and it's quiet so we could talk on the shore.","ja":"一緒に海に行こうかあんまり人がいない静かな砂浜でお話ししよう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_alo_3#originalText","id":"talk.vc.home_season_asuna_alo_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"秋夜悠长，在同一个房间一起读书渡过也感觉挺开心的。","en":"On long autumn nights, I'm looking forward to spending time together reading in the same room.","ja":"秋の夜長は、同じ部屋で一緒に読書をして過ごすのも楽しそうね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_alo_4#originalText","id":"talk.vc.home_season_asuna_alo_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"每到冬天，我都会回想起，这是和你相遇的重要季节。","en":"I remember clearly whenever it's winter. It's a special season since that's when I met you.","ja":"冬になると、きっと思い出すわあなたと出会った、大切な季節だもの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_swim_1#originalText","id":"talk.vc.home_wait_asuna_alo_swim_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这件泳装会不会太性感了……不过偶尔也还好吧？呵呵。","en":"I wonder if this swimsuit was a little too bold... Hehe. It should be fine, once in awhile.","ja":"ちょっとこの水着大胆だったかな……たまにはいいよね、ふふ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_swim_1#originalText","id":"talk.vc.home_touch_asuna_alo_swim_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不把头发吹干很容易生病喔。","en":"I need to dry my hair! Otherwise, I'll catch a cold!","ja":"髪、乾かさないと風邪ひいちゃうね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_swim_4#originalText","id":"talk.vc.home_touch_asuna_alo_swim_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"哇！你、你刚刚手碰到胸……真是的！！！","en":"Kyaaa! D-Did a hand just... My chest... I've just about had it!","ja":"きゃっ!い、今胸に手が……もう!!!"},"kind":"dialogue"},{"uid":"talk.vc.home_asuna_real_student_wait_1#originalText","id":"talk.vc.home_asuna_real_student_wait_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我做了便当，嘿嘿，我比平常还要努力做的哦！","en":"I made a lunch box for you! Hehe, I poured my heart and soul into it!","ja":"お弁当作ってきたよふふ、いつもより張り切っちゃった!"},"kind":"dialogue"},{"uid":"talk.vc.home_asuna_real_student_wait_2#originalText","id":"talk.vc.home_asuna_real_student_wait_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"放学后要怎么办？在ALO集合也是可以……但偶尔来个制服约会应该也不错吧。","en":"Any plans after school? We could meet on ALO...But a date in our uniforms would be nice too!","ja":"放課後はどうするの?ALOで集合してもいいけど……たまには制服デートもいいなぁ"},"kind":"dialogue"},{"uid":"talk.vc.home_asuna_real_student_wait_3#originalText","id":"talk.vc.home_asuna_real_student_wait_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"能在这所学校上学真是太好了，可以和大家见面，也可以……每天见到你。","en":"I'm so happy I get to go to this school. I get to meet everyone every day...And you.","ja":"この学校に通えて良かったなみんなに会えるし君にも……毎日会えるしね"},"kind":"dialogue"},{"uid":"talk.vc.home_asuna_real_student_touch_1#originalText","id":"talk.vc.home_asuna_real_student_touch_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"嗯……喜欢被你摸头。","en":"...I like it when you pet me like that!","ja":"うん……君になでられるの好き"},"kind":"dialogue"},{"uid":"talk.vc.home_asuna_real_student_touch_2#originalText","id":"talk.vc.home_asuna_real_student_touch_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"等，等一下啦……在这种地方制服不是会弄乱吗！","en":"W-wait...I can't get my uniform dirty in a place like this!","ja":"ちょ、ちょっと……こんなところで制服乱れちゃうじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_asuna_real_student_time_1#originalText","id":"talk.vc.home_asuna_real_student_time_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"一脸想睡的样子呢，可不能在上课中打瞌睡哦！","en":"Hey sleepyhead! You better not take a nap during class!","ja":"まだ眠たそうだね授業中に居眠りしちゃダメだよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_1#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这件礼服……你觉得如何？穿成这样虽然令人害羞，但能让你高兴就好……","en":"What do you think of this dress? I feel a little silly in it, but I'll wear it if it makes you happy.","ja":"このドレス……どうかな?恥ずかしいけど、君に喜んでもらえるなら……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_2#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"直到不久之前，我根本没考虑过结婚这种事……不过如果是跟你，我愿意。","en":"Marriage... I'd never considered it before, but...I might change my mind for you.","ja":"結婚なんて、少し前までは考えもしなかったけど……君となら、って思う"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_3#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"晚点要不要一起去购物？我们把一些东西换新，用来纪念这个日子吧。","en":"Wanna go shopping? Let's get some upgrades to celebrate.","ja":"これから、ショッピングにいかない?記念にいろいろ新調しようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_4#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这种事情，是不是该正式通知大家比较好……感觉真难为情呢。","en":"Maybe this is the sort of thing we should announce to people? It just feels...kinda embarrassing.","ja":"こういうの、みんなにちゃんと言った方がいいのかなあ……なんか、照れくさいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_5#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然西式婚礼也不错，但也有点向往穿着日式礼服举行神前式呢。","en":"Western-style weddings are great and all, but I've always kinda liked Japanese wedding kimono.","ja":"洋風の結婚式もいいけど和装でやる神前式にもちょっと憧れちゃうなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_6#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天这个日子，就跟生日一样……不对，对我而言，将会是比生日更特别的日子。","en":"Today is just as special to me as my birthday... No, it's even more special.","ja":"今日は、誕生日と同じくらい……ううん、それ以上にわたしにとって特別な日になるの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_7#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要办婚礼的话，比起家人和亲戚，我更希望邀请在这里遇到的伙伴们出席呢。","en":"If I do have a wedding, I'd rather have it in VR with my friends than in the real world, with my family.","ja":"結婚式をやるとしたら家族や親戚より、ここで出会ったみんなに出席してほしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_8#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我们这样，是新婚夫妻……对吧？呵呵呵……「新婚夫妻」听起来真是甜美。","en":"You and I are...newlyweds...right? Hahaha... Newlyweds has such a lovely ring to it.","ja":"わたしたち、新婚……なんだよねふふふ……「新婚」っていい響き"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_alo_wedding_9#originalText","id":"talk.vc.home_wait_asuna_alo_wedding_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"抱歉，这件礼服穿起来很费工夫……让你等了很久吧！？","en":"Sorry, this dress is a real hassle to get changed into... I hope I didn't hold you up too long?","ja":"ごめんね、このドレス着るのが大変で……待たせちゃったよね!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_wedding_1#originalText","id":"talk.vc.home_touch_asuna_alo_wedding_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我本来想花更多心思在发型上……但在游戏里面还是有极限。","en":"I wish I could've done something more complex with my hairstyle... but games have their limits.","ja":"ヘアアレンジ、もうちょっと工夫したかったんだけど……ゲームの中だと限界があって"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_wedding_2#originalText","id":"talk.vc.home_touch_asuna_alo_wedding_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"掀开新娘的头纱之后，要做的就只有一件事……对吧？","en":"After you lift a bride's veil, there's only one thing left to do... Get it?","ja":"花嫁のベールを上げたらすることはひとつ……だよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_wedding_3#originalText","id":"talk.vc.home_touch_asuna_alo_wedding_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不可以一直碰，好不容易打理好的发型会乱掉啦。","en":"Don't touch my hair, okay? I just had it styled.","ja":"あんまり触っちゃダメせっかくセットした髪型が崩れちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_wedding_4#originalText","id":"talk.vc.home_touch_asuna_alo_wedding_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"喂，礼服会乱掉啦。真是的……再忍一下就好，懂了吗？","en":"Hey, you're making my dress slip! Oh, you... Be a little more patient, okay?","ja":"ちょっと、ドレスがずれちゃうよもう……あと少しだけ我慢してね、わかった?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_wedding_5#originalText","id":"talk.vc.home_touch_asuna_alo_wedding_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……嗯，用力抱紧我，我想要更深刻地感受你。","en":"...Please, hug me tight. I want to feel you, to feel that this is real.","ja":"……うん力いっぱい抱きしめてもっと君を感じたいから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_wedding_6#originalText","id":"talk.vc.home_touch_asuna_alo_wedding_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"嗯，我发誓会永远爱你，永远不和你分离，不论是在怎样的世界都一样。","en":"I pledge my eternal love to you. I will be by your side forever, no matter what world you are in.","ja":"うん、永遠の愛を誓うよずっと君と一緒にいるたとえそこが、どんな世界であっても"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_wedding_7#originalText","id":"talk.vc.home_touch_asuna_alo_wedding_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我说，你觉得我……美吗？……谢谢，我就知道你会愿意捧场。","en":"So, how do I look? Thank you. I knew you would say something like that!","ja":"ね、わたし……綺麗かな?……ありがとうそう言ってくれるって、知ってた"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_alo_wedding_8#originalText","id":"talk.vc.home_touch_asuna_alo_wedding_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你的这双手拯救了我，而我今后将一直握着你的手，走过下半辈子呢。","en":"Your loyal touch saved my life. And I'll live the rest of my life with your hand in mine.","ja":"この手が、わたしを救ってくれたそしてこれからは、ずっとこの手を握って、わたしは生きていくんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_wedding_1#originalText","id":"talk.vc.home_time_asuna_alo_wedding_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"幸好今天有放晴，毕竟是我们开始新生活的大好日子嘛。","en":"I'm so glad it's a nice day. Perfect weather for us to set sail into the next chapter of our lives.","ja":"今日、晴れてよかったねわたしたちの新しい船出の日だもの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_wedding_2#originalText","id":"talk.vc.home_time_asuna_alo_wedding_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"来，差不多该起床了。今天是很重要的日子，要是睡过头可就糟糕了喔。","en":"Come on, wake up! It's a special day today. You don't want to sleep through it.","ja":"はい、そろそろ起きて今日は大事な日なんだから寝坊したら大変よ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_wedding_4#originalText","id":"talk.vc.home_time_asuna_alo_wedding_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"婚宴的料理也全都是我自己做的喔。因为，这可是我们的婚礼啊。","en":"I cooked all the wedding food myself! It's our wedding after all.","ja":"ウエディングの料理も全部自分で作ったんだだって、わたしたちの式だもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_wedding_5#originalText","id":"talk.vc.home_time_asuna_alo_wedding_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要我直接以这个打扮走出门，实在让人难为情耶……","en":"I'm a little too embarrassed to go out in public dressed like this.","ja":"この姿で、普通に外に出るのはさすがに恥ずかしいなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_wedding_7#originalText","id":"talk.vc.home_time_asuna_alo_wedding_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天有点累人呢。不过……能得到大家的祝福真是太好了。","en":"Today was pretty exhausting... But I'm glad we got to celebrate with all our friends.","ja":"今日は少し疲れちゃったねでも……みんなにお祝いしてもらえてよかったな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_wedding_8#originalText","id":"talk.vc.home_time_asuna_alo_wedding_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天晚餐就煮清淡一点吧，白天时已经吃了许多好料嘛。","en":"Let's have a light supper today. We did gorge at the reception earlier.","ja":"今日の夕飯は軽めにしようか昼間、たくさんご馳走食べちゃったもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_wedding_10#originalText","id":"talk.vc.home_time_asuna_alo_wedding_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……不知为何睡不着呢。我一直觉得好亢奋，心脏跳个不停。","en":"I just...can't sleep. I'm so wired that my heart won't stop pounding.","ja":"……なんだか眠れないね気持ちがすごく高揚してドキドキがずっと続いてる"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_alo_wedding_11#originalText","id":"talk.vc.home_time_asuna_alo_wedding_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"欸，牵着我的手吧。今天，我想这样一直握着手入眠。","en":"Can we hold hands? I want to hold hands all night while we sleep.","ja":"ねえ、手を握って?今日は、ずっとこうして手を繋いだまま寝ようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_alo_wedding_11#originalText","id":"talk.vc.home_day_asuna_alo_wedding_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"从今天起，新的一周又要开始了。我们一起努力吧！","en":"Another week starts today. Let's crush it together again!","ja":"今日から新しい一週間が始まるね一緒に頑張ろう!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_alo_wedding_12#originalText","id":"talk.vc.home_day_asuna_alo_wedding_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"只要想到晚上回家可以见到你，我就能打起精神面对白天的种种。","en":"Knowing I'll see you when I get home at night gives me all the energy I need for the day's work.","ja":"夜帰ったら君に会えるって思ったら、昼間の色んなことも頑張れるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_alo_wedding_13#originalText","id":"talk.vc.home_day_asuna_alo_wedding_13","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天就一直待在这里享受两个人的悠闲时光，你觉得怎么样？","en":"I want to spend the whole day together doing nothing. How does that sound to you?","ja":"今日は、ずっとこっちにいてふたりでのんびりするのはどうかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_alo_wedding_14#originalText","id":"talk.vc.home_day_asuna_alo_wedding_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"现实世界已经是半夜了呢。这边明明还这么明亮……没办法，明天再见……吧。","en":"It's actually already night. Hard to believe, since it's so light... Oh well. See you tomorrow.","ja":"現実は、もう夜中だねこっちはこんなに明るいのに……しょうがない、また明日……ね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_1#originalText","id":"talk.vc.home_event_asuna_alo_wedding_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"新年快乐，与你共享的新的一年又开始了呢。","en":"Happy New Year. I'm excited to spend another year together.","ja":"あけましておめでとう君との新しい一年がまた始まったね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_2#originalText","id":"talk.vc.home_event_asuna_alo_wedding_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"节分时要拿沙丁鱼的头当装饰对吧？不晓得这个世界有没有沙丁鱼。","en":"You're supposed to decorate with sardine heads on Setsubun. Does this world have sardines?","ja":"節分には、鰯の頭を飾るんだよねこの世界にも、鰯ってあるのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_3#originalText","id":"talk.vc.home_event_asuna_alo_wedding_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我猜你会收到很多巧克力，但我送的一定最好吃。","en":"I assume many girls will give you chocolate, but I'm sure mine will be the tastiest.","ja":"君はたくさんチョコもらうと思うけど、わたしのがきっと一番おいしいと思うよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_4#originalText","id":"talk.vc.home_event_asuna_alo_wedding_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这个娃娃，你不觉得有点像结衣吗？好可爱喔。","en":"Don't you think this doll kind of looks like Yui? Gosh, she's so cute.","ja":"このお人形、ちょっとユイちゃんに似てると思わない?すっごくかわいいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_5#originalText","id":"talk.vc.home_event_asuna_alo_wedding_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你问我想要什么回礼？这样的话……今天一整天，你可以陪着我吗？","en":"What would I like for White Day? Let's see... How about, we spend the whole day together?","ja":"お返しに欲しいもの?それじゃ……今日一日わたしとずっと一緒にいてくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_6#originalText","id":"talk.vc.home_event_asuna_alo_wedding_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你想到什么玩笑话了吗？我当然看得出来啊，都跟你相处这么久了。","en":"Okay, what joke did you just think of? Come on, I've known you for years. You can't hide it from me.","ja":"どんなジョークを思いついたの?わかるよ、君とずっと一緒にいるんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_7#originalText","id":"talk.vc.home_event_asuna_alo_wedding_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"放连假也都泡在这种游戏里面，感觉真有我们的作风呢。","en":"Spending a week-long vacation inside a VR game... Yeah, that's pretty \"us.\"","ja":"連休がこういうゲームの中っていうのも、なんだかわたしたちらしいね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_8#originalText","id":"talk.vc.home_event_asuna_alo_wedding_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"为什么会有六月新娘这个说法呢？在日本明明就是雨季。","en":"I wonder why June brides are a thing? That's the rainy season in Japan.","ja":"なんでジューンブライドっていうんだろうね日本だと、雨の時期なのに"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_9#originalText","id":"talk.vc.home_event_asuna_alo_wedding_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"织女和牛郎，是被硬生生拆散的对吧？换作是我，绝对不会容许那种事发生。","en":"Poor Orihime and Hikoboshi were forced apart. I would never let that happen to us.","ja":"織姫と彦星って、無理やり引き離されちゃったんだよねそんなの、わたしなら絶対許さないな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_10#originalText","id":"talk.vc.home_event_asuna_alo_wedding_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"没有其他游客的私人海滩是不错，但我也想跟结衣去一般的海水浴场看看呢。","en":"Private beaches are nice and all, but I would love to take Yui to a waterpark someday.","ja":"誰もいないプライベートビーチもいいけど、ユイちゃんと一緒に普通の海水浴に行きたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_11#originalText","id":"talk.vc.home_event_asuna_alo_wedding_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"整个暑假几乎都和你在一起……所以我真的过得很开心。","en":"Summer vacation was so much fun this year! Probably...because I was with you the whole time.","ja":"夏休みは、ほとんどの間君と一緒にいたから……すっごく楽しかった"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_12#originalText","id":"talk.vc.home_event_asuna_alo_wedding_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天要赏月，所以入夜之后大家都会来喔。得在那之前做好准备才行。","en":"It's the moon-viewing festival today! Our friends are coming over tonight, so we'd better tidy up.","ja":"今日はお月見だから夜になったらみんなが来るよそれまでに準備しないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_13#originalText","id":"talk.vc.home_event_asuna_alo_wedding_13","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天要是换上这套礼服，会不会被人认为是在扮装啊？","en":"If I wear a dress like this today, will people think it's a costume?","ja":"今日、こんなドレス着てたら仮装だと思われちゃうかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_14#originalText","id":"talk.vc.home_event_asuna_alo_wedding_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我还是忘不了这一天，不过，我隐约觉得它好像慢慢变成了美好的回忆。","en":"I know I'll never forget this day. I get the feeling it'll become a really fond memory for me.","ja":"やっぱり、この日は忘れられないでも、だんだんといい思い出になっていくような、そんな気がする"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_alo_wedding_15#originalText","id":"talk.vc.home_event_asuna_alo_wedding_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"两个人独处的圣诞节，感觉就是不一样呢。相信明年一定也是你和我……","en":"Christmas is so much more special when it's just you and me. Let's do this again next year...","ja":"ふたりっきりのクリスマスはやっぱり特別だね来年も、きっとふたりで……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_alo_wedding_3#originalText","id":"talk.vc.home_bd_asuna_alo_wedding_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要先想好自己想要的生日礼物喔，不准说「什么都可以」！","en":"Think about what you want for your birthday, okay? And, \"I'm fine with whatever\" is not an option!","ja":"誕生日プレゼント、欲しいもの考えておいてね「何でもいい」は無しで!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_alo_wedding_5#originalText","id":"talk.vc.home_bd_asuna_alo_wedding_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"比起在现实世界庆祝，或许爱丽丝小姐会比较喜欢到这边庆生吧。","en":"Alice would probably rather we celebrate in VR instead of IRL.","ja":"アリスさんは、現実でお祝いするより、この中で祝った方が喜ぶかもしれないね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_alo_wedding_7#originalText","id":"talk.vc.home_bd_asuna_alo_wedding_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我一直很感谢莉法，所以今天我想大家一起盛大地为她庆生。","en":"I can never thank Leafa enough. So I want to give her a big party with all her friends today.","ja":"リーファちゃんには感謝してるのだから今日は、みんなで盛大にお祝いしてあげたいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_alo_wedding_8#originalText","id":"talk.vc.home_bd_asuna_alo_wedding_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是小诗诗的生日，我们一起去《GGO》吧？我想这样她一定很开心。","en":"Why don't we play GGO today for Shino-non's birthday? She'd probably love that.","ja":"シノのんのお誕生日だからふたりで《GGO》に行こうかその方がきっと喜ぶよね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_alo_wedding_11#originalText","id":"talk.vc.home_bd_asuna_alo_wedding_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是罗妮耶小姐的生日，希望某天能再到另一个世界去为她庆生呢。","en":"It's Ronie's birthday today. I'd love to go to her world again sometime and throw her a party.","ja":"今日はロニエさんのお誕生日いつかまた向こうの世界に行ってお祝いしてあげたいね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_alo_wedding_12#originalText","id":"talk.vc.home_bd_asuna_alo_wedding_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是缇洁小姐的生日呢。等下次见到面，我们再像之前那样为她盛大庆生吧。","en":"It's Tiese's birthday today. When we finally get to see her again, let's have a big party.","ja":"今日はティーゼさんのお誕生日ねまた会えたら、いつかみたいに盛大にお祝いしようね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_alo_wedding_14#originalText","id":"talk.vc.home_bd_asuna_alo_wedding_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"差不多该去为莉兹庆生了。我们早点过去，帮忙做准备吧。","en":"We should head to Liz's birthday party soon. I want to get there early so we can help set up.","ja":"そろそろリズのお祝いに行こうか早めに行って、準備を手伝いましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_alo_wedding_15#originalText","id":"talk.vc.home_bd_asuna_alo_wedding_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"西莉卡很可爱，所以我想送她饰品。其实，我已经请莉兹帮我制作了。","en":"I'm thinking of giving Silica some jewelry, since she's so cute. I've actually got Liz on the case.","ja":"シリカちゃんはかわいいからアクセサリーを贈ろうと思うの実は、リズに頼んであるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_alo_wedding_1#originalText","id":"talk.vc.home_etc_asuna_alo_wedding_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"达成目标了呢！是不是又进步了啊？","en":"You've reached your goal! Have you been improving while I wasn't looking?","ja":"目標達成だね!また成長したんじゃない?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_alo_wedding_2#originalText","id":"talk.vc.home_etc_asuna_alo_wedding_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"是不是有礼物送来了？那个，我可以跟你一起确认内容吗？","en":"You got a gift, right? Can I watch you open it?","ja":"ギフトが来てるんじゃない?ねえ、わたしも一緒に中を確認してもいい?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_alo_wedding_3#originalText","id":"talk.vc.home_etc_asuna_alo_wedding_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"是新任务的情报呢，要不要我们两个人一起去挑战看看？","en":"There's a new quest out. Want to try it out together?","ja":"新しいクエストの情報だねちょっとふたりでチャレンジしてみる?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_1st_1#originalText","id":"talk.vc.home_wait_asuna_1st_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽说像这样待在你身边已经变成理所当然了……但这仍是件很幸福的事情呢。","en":"I've gotten so used to being with you...that I sometimes forget how happy I am.","ja":"こうやって隣にいるのが当たり前になってたけど……幸せなことなんだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_1st_2#originalText","id":"talk.vc.home_wait_asuna_1st_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"无论你要去哪里，我都会跟着去的。我一定会陪伴你到天涯海角。","en":"No matter where you go, I'm coming with you. Always. Anywhere and everywhere.","ja":"君がどこに行くとしてもわたしはついていくよ絶対に、どこまででも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_1st_3#originalText","id":"talk.vc.home_wait_asuna_1st_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我学到新的食谱啰！下次来煮，你要尝尝看喔。","en":"I just mastered a new recipe! Get your taste buds ready.","ja":"新しいレシピを覚えたの!今度作るから、食べてみて"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_1st_4#originalText","id":"talk.vc.home_wait_asuna_1st_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"无论到哪里都有好多对手呢……","en":"No matter where I go, there's always so many rivals.","ja":"どこに行っても、ライバルが多いなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_1st_9#originalText","id":"talk.vc.home_wait_asuna_1st_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你沉思时的表情我也很喜欢呢……咦？你听见了！？没……没什么啦！","en":"I love the way you look when you're deep in thought... Ack, you heard that? F-Forget it!","ja":"考え事してる顔も、好き……え、聞こえちゃった!?な……なんでもないから!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_1st_1#originalText","id":"talk.vc.home_touch_asuna_1st_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"好久没有换发型了呢～反正我们在VR里面，其实也可以随意变换造型啦。","en":"You've not changed your hairstyle all this time. You know, since it's VR, you could change it.","ja":"髪型はずっと変えてないなあVRの中だから、自由に変えてもいいんだけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_1st_2#originalText","id":"talk.vc.home_touch_asuna_1st_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"有很香的味道？唔～我猜大概是洗发精的味道吧……","en":"I smell good? Hmmm... It's probably my shampoo.","ja":"いい匂いがする?うーん、たぶんシャンプーの匂いだと思うけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_1st_4#originalText","id":"talk.vc.home_touch_asuna_1st_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"想碰我就不要畏畏缩缩的，应该要更用力地抱紧我。","en":"If you're gonna touch me, don't be so timid. Just go in for a hug!","ja":"触るなら、おっかなびっくりじゃなくて、もっとギュッとして"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_1st_5#originalText","id":"talk.vc.home_touch_asuna_1st_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"多少要考虑一下别人的目光喔。再说也会影响结衣的教育嘛……","en":"Hey, consider our surroundings, will you? This isn't good for Yui's upbringing...","ja":"少しは人目を考えてよねユイちゃんの教育にもあんまりよくないんだから……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_1st_6#originalText","id":"talk.vc.home_touch_asuna_1st_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"真希望身材能更好一点……","en":"I wish I had a nicer figure...","ja":"もうちょっとスタイルよくなりたいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_1st_1#originalText","id":"talk.vc.home_time_asuna_1st_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"早上可以喝点热汤来暖和身体喔。","en":"I love soup in the morning. It's so warm and comforting.","ja":"朝は温かいスープで体を温めるといいんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_1st_4#originalText","id":"talk.vc.home_time_asuna_1st_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天就把饭带到外面吃吧。我会大展厨艺的！","en":"We're eating lunch outside today, right? Don't worry, I'm going all out with our bento!","ja":"今日は外でお弁当にしよう?腕によりをかけて作っちゃうから!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_1st_7#originalText","id":"talk.vc.home_time_asuna_1st_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天一整天也辛苦你了。有没有发生什么开心的事情呢？","en":"Another hard day's work in the books. Anything fun happen today?","ja":"今日も一日お疲れさま今日は、どんな楽しいことがあったの?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_1st_10#originalText","id":"talk.vc.home_time_asuna_1st_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……今天的月色很美，在夜里散步一下吧。","en":"The moon is so pretty tonight... Wanna go for a walk?","ja":"……今日は月が綺麗だから少しだけ夜のお散歩しよっか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_1st_1#originalText","id":"talk.vc.home_day_asuna_1st_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"从星期一开始就这么没精神的话，这一周都会一直这样喔？","en":"If you're already exhausted on Monday, then there goes your whole week.","ja":"月曜日からぐったりしてると1週間ずっとそうなっちゃうわよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_1st_2#originalText","id":"talk.vc.home_day_asuna_1st_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"疲劳快累积到一定程度了吧。泡个温一点的澡，然后好好休息吧。","en":"You're probably feeling pretty tired by now. How about a nice warm bath and then bedtime?","ja":"そろそろ疲れがたまる頃ね少しぬるいお風呂に入ってゆっくり休みましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_1st_3#originalText","id":"talk.vc.home_day_asuna_1st_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天要出门吗？还是要一整天都待在家里呢？","en":"Want to go out today? Unless you'd rather just stay in?","ja":"今日はお出かけする?それとも、一日ずっとお家にいようか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_1st_4#originalText","id":"talk.vc.home_day_asuna_1st_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"感觉明天开始又能继续努力了吗？呵呵，很棒。那我们差不多该睡了吧。","en":"All rested up for tomorrow? Hehe. Good. Now let's get some sleep.","ja":"明日から、また頑張れそう?ふふ、よろしいそれじゃそろそろ寝ましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_1st_1#originalText","id":"talk.vc.home_season_asuna_1st_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"春天的野菜好好吃呢。下次我们一起去摘野菜吧。","en":"Wild plants are so yummy in early spring. We should go foraging sometime.","ja":"春の山菜っておいしいよね今度一緒に採りにいこうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_1st_2#originalText","id":"talk.vc.home_season_asuna_1st_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"夏天的饭菜很容易坏掉，得多加注意才行。","en":"Food goes bad really easily in the summer, so we need to be careful.","ja":"夏は、ご飯がすぐ悪くなっちゃうから、気をつけないと"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_1st_3#originalText","id":"talk.vc.home_season_asuna_1st_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"秋天总是不知不觉间就转凉了呢。一不小心就会忘记要加件外套。","en":"Autumn's chill just sneaks up on you, doesn't it? I always regret not bringing a jacket.","ja":"秋って、いつの間にか寒くなってるよねつい上着忘れちゃうの"},"kind":"dialogue"},{"uid":"talk.vc.home_season_asuna_1st_4#originalText","id":"talk.vc.home_season_asuna_1st_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"冬天有好多节庆活动呢。呵呵，真令人期待。","en":"I love how winter is full of fun events. Hehe, I'm so excited.","ja":"冬ってイベントがたくさんあるよねふふ、楽しみだなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_1#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这一带很安静，感觉不错呢。和最前线的楼层完全不一样，让人感到很平静。","en":"I love how quiet and relaxing this place is. It's completely unlike the front line floors.","ja":"この辺りは、静かでいいね最前線のフロアとは全然違うなんだか落ち着くね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_2#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我说……再一下就好，要不要继续这样待着？","en":"Hey... Can we just stay like this a little bit longer?","ja":"ねえ……もう少し、このままでいない?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_3#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你的身边，是全世界最让人放心的地方。至少对我来说是这样。","en":"The safest place in this world is by your side. That's how it is for me, at least.","ja":"君のそばが、この世界で一番安心できる場所なの少なくとも、わたしにとっては"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_4#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你眼珠的颜色……就像是漂亮的夜空。第一次看见你的时候，我就像是要被吸进去一样。","en":"Your eyes are so beautiful...black as the night sky. When I first met you, I almost lost myself in them.","ja":"君の瞳……綺麗な夜空の色最初に見た時から、吸い込まれそうって思ってたの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_5#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天……能再多陪我一下吗？","en":"Just for today...will you come just a bit closer to me?","ja":"今日は……もう少しだけそばにきてくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_6#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要是每天都能这样悠闲度日，那肯定会很幸福。","en":"If only we could just hang out and relax like this every day... How happy our lives would be.","ja":"こんな風に、毎日のんびりできたら幸せなんだろうなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_7#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"也差不多该吃饭了吧？和你在一起的时候，就连我都会跟着睡个不停。","en":"I suppose we really have to get breakfast now. I feel like I could stay in bed with you all day.","ja":"さすがに、そろそろご飯かな君と一緒にいると、わたしまでいつまでも寝ちゃうから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_8#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然也碰过许多挫折，但我现在很幸福。因为你就在我身边。","en":"I've had my share of pain in the past, but I'm very happy now... because I have you.","ja":"辛いこともいっぱいあったけど今は幸せだよ君がそばにいてくれるから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_sao_sleeping_9#originalText","id":"talk.vc.home_wait_asuna_sao_sleeping_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……你睡觉时的脸庞，真的是怎样都看不腻。","en":"I love the look of your sleeping face. I could stare at it all night.","ja":"……いつまで見てても飽きないな寝てる時の、君の顔"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_sleeping_1#originalText","id":"talk.vc.home_touch_asuna_sao_sleeping_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"整理头发很轻松这点，算是《SAO》少数的优点之一。男生应该很难理解吧？","en":"One of the few pluses about SAO is how easy haircare is. Though I guess a boy wouldn't understand.","ja":"髪のお手入れが楽なのは数少ない《SAO》のいいところね男の人には、わからないかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_sleeping_2#originalText","id":"talk.vc.home_touch_asuna_sao_sleeping_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"头发被你摸的时候，是很舒服没错，可是有种……难以言喻的感觉……","en":"Having my hair touched...it feels good, but it also makes me feel... kind of weird.","ja":"髪を触られるの、気持ちいいんだけどなんだか……変な気分になっちゃって……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_sleeping_3#originalText","id":"talk.vc.home_touch_asuna_sao_sleeping_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……呐，再靠近一点。近到彼此的额头可以贴在一起。","en":"Hey, come closer... So close that our foreheads are almost touching.","ja":"……ね、もっとこっちに来ておでことおでこがくっついちゃうくらいまで"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_sleeping_4#originalText","id":"talk.vc.home_touch_asuna_sao_sleeping_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你竟敢～那我也要反击啰！","en":"Oh, now you've done it... Well, two can play at that game!","ja":"やったな〜?それじゃこっちからもお返しするからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_sleeping_5#originalText","id":"talk.vc.home_touch_asuna_sao_sleeping_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……我确实感受到了。就算这里只是虚拟世界，我也能感觉到你手心的温暖。","en":"I can still feel your warmth... Even though this is a virtual world, it still comes through.","ja":"……ちゃんと感じるよたとえここが仮想世界でも君の手のぬくもりが伝わってくる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_sleeping_6#originalText","id":"talk.vc.home_touch_asuna_sao_sleeping_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就算没人在看，也别这样嘛。……你就这么想摸吗？","en":"Hey! Just because nobody's watching, that doesn't... Do you really want to touch me that badly?","ja":"もう、誰も見てないからって……そんなに触りたいの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_sleeping_7#originalText","id":"talk.vc.home_touch_asuna_sao_sleeping_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"能转过身一下吗？呵呵，你的背……真的很宽耶。","en":"Hey, can you stay turned away for a bit longer? Heehee... Your shoulders are so...broad.","ja":"ねえ、少し向こう向いてくれる?ふふ、やっぱり君の背中……広いね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_asuna_sao_sleeping_8#originalText","id":"talk.vc.home_touch_asuna_sao_sleeping_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"能像这样和你待在一起亲密接触，感觉好像是在做梦。","en":"This feels like a dream. Just, sharing space with you and touching you like this.","ja":"なんだか夢みたいだねこうやって、ふたりで同じ場所で触れ合ってるなんて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_sleeping_1#originalText","id":"talk.vc.home_time_asuna_sao_sleeping_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那个……一变亮之后，感觉有点不好意思。","en":"Um...when it's light, I feel kind of self-conscious.","ja":"その……明るくなるとなんだか恥ずかしいね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_sleeping_2#originalText","id":"talk.vc.home_time_asuna_sao_sleeping_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天特别允许你赖床。所以，那个……靠过来……一点？","en":"Just for today, I'll let you sleep in. So, hey come...closer.","ja":"今日だけは、お寝坊も許しますだから、ほら……ここ……きて?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_sleeping_4#originalText","id":"talk.vc.home_time_asuna_sao_sleeping_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我说，要不要一起出门？我会用心做好久没做的便当的。","en":"Hey, wanna go out somewhere? I'll even make one of my famous picnic lunches.","ja":"ね、ふたりでお出かけしない?久しぶりにお弁当張り切っちゃうから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_sleeping_5#originalText","id":"talk.vc.home_time_asuna_sao_sleeping_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"天气这么好，却窝在床上睡觉……似乎也太享受了吧？","en":"Look at us, lying in bed on such a nice day... I kind of feel like royalty.","ja":"お天気がいいのに、こうやってベッドで寝てるのって……なんだか、すごく贅沢かも"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_sleeping_7#originalText","id":"talk.vc.home_time_asuna_sao_sleeping_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"饭后收拾我来就好，你先去洗澡。","en":"Go ahead and shower ahead of me. I'm going to clean the dishes first.","ja":"ご飯の後片付けはやっておくから先にシャワー行ってきて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_sleeping_8#originalText","id":"talk.vc.home_time_asuna_sao_sleeping_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然时间还有点早……要不要先睡了？","en":"It's still a bit early... but wanna just turn in?","ja":"少し早いけど……今日はもう寝ちゃおうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_sleeping_10#originalText","id":"talk.vc.home_time_asuna_sao_sleeping_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你醒着吗？……呵呵，我也还醒着喔。","en":"Hey...are you still awake? Haha... Me too.","ja":"ね、起きてる?……ふふ、わたしも起きてるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_asuna_sao_sleeping_11#originalText","id":"talk.vc.home_time_asuna_sao_sleeping_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"穿透过窗帘的月光，看起来十分梦幻。或许是因为和你在一起吧？","en":"The moonlight through the curtain always looks so magical... Maybe it's that you've cast a spell on me.","ja":"カーテンから漏れる月の光ってすごく幻想的に見えるそれとも、君が一緒だからかな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_sleeping_1#originalText","id":"talk.vc.home_day_asuna_sao_sleeping_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"从今天起，又要开始推进度了。不过，你放心。以后我们会一直在一起的。","en":"Starting today, we have to go on raids again. But I'll be fine, now that I have you by my side.","ja":"今日からは、また攻略の日々だねでも、大丈夫これからはずっと一緒だもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_sleeping_2#originalText","id":"talk.vc.home_day_asuna_sao_sleeping_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"如果累了，要好好休息喔。你可以跟我撒娇没关系。","en":"Hey, it's okay to rest if you're tired. Let me take care of you.","ja":"ねえ、疲れたらちゃんと休んでねわたしには甘えていいんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_sleeping_3#originalText","id":"talk.vc.home_day_asuna_sao_sleeping_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"生活有计划性是不错，但只要能和你一起悠哉过下去，做什么我都很开心。","en":"Making plans is nice and all, but as long as I'm with you, I don't really care what we do.","ja":"予定を立てるのもいいけどゆっくりふたりだけで過ごせるなら何をしてても楽しいな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_sao_sleeping_4#originalText","id":"talk.vc.home_day_asuna_sao_sleeping_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"帮我充电一下，让我能努力到下次休假。给我一个抱抱。","en":"Hey...can you help me recharge, so I can make it to my next day off? Just hold me tight.","ja":"ねえ、次のお休みまで頑張れるように、充電して?ギュッとしてほしいの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_1#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"新年快乐。在新的一年，我们也要一直在一起喔。","en":"Happy New Year! I hope you're by my side just as much as you were last year.","ja":"あけましておめでとう新しい一年も、ずっとわたしのそばにいてね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_2#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"豆子的数量要和年龄一致，对吧？来，我喂你吃。张嘴，啊～","en":"You're supposed to eat your age in beans, right? I'll feed you. Say ahh.","ja":"豆は歳の数だけ、だよねほら、食べさせてあげるあーん"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_3#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，你不用一副望眼欲穿的表情啦。我已经准备好你的巧克力了。当然是本命的喔。","en":"Haha, yes, don't worry, I got you some chocolates. For my true valentine, of course.","ja":"ふふ、そんな顔しなくてもちゃんとチョコ用意してるよもちろん、本命だからね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_4#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"女儿节是女孩子的节日，结衣应该会很开心。我们三人一起庆祝吧。","en":"Hinamatsuri is a festival for girls, so Yui might like it. Shall we celebrate with her?","ja":"ひな祭りは女の子の節句だからユイちゃんが喜ぶかも3人でお祝いしようか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_5#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……嗯，其实我一直很期待你会回送我什么东西。","en":"Yeah...I was actually hoping you'd get me a White Day gift. I kept guessing what it might be.","ja":"……うん、実は期待してた君がどんなものを、お返ししてくれるのかなって"},"kind":"dialogue"}]};
